const tabId = 1962625075;
const callerInfo = await browserjs(tabId, async () => {
  const res = await fetch("https://static.wineaccess.com/nuxt3/_nuxt/CbYvg233.js");
  const text = await res.text();
  // Find calls to p(
  const matches = [];
  let idx = 0;
  while ((idx = text.indexOf('.searchProducts(', idx)) !== -1) {
    matches.push(text.slice(Math.max(0, idx - 100), idx + 100));
    idx += 16;
  }
  // Let's also check for how route query is converted to filters
  let idx2 = 0;
  const matches2 = [];
  while ((idx2 = text.indexOf('appliedFilters', idx2)) !== -1) {
    matches2.push(text.slice(Math.max(0, idx2 - 100), idx2 + 100));
    idx2 += 14;
  }
  return { matches, matches2 };
});
console.log(JSON.stringify(callerInfo, null, 2));

