const tabId = 1962625075;
const analyze47 = await browserjs(tabId, async () => {
  const res = await fetch('/api/catalog/search/?show_sold_out=1&region__in=oregon&page_size=100');
  const data = await res.json();

  // Filter for:
  // 1. Red or White wine (wine_category or main_varietal)
  // 2. Price < $40
  // 3. Food pairing: fish or dessert (sweets)

  const matches = data.results.filter(w => {
    // Price under $40
    const price = w.price_excl_tax;
    if (price >= 40) return false;

    // Food pairing: fish or dessert (sweets)
    const pairings = w.food_pairings || [];
    const pairsWithFishOrDessert = pairings.includes('fish') || pairings.includes('sweets') || pairings.includes('dessert');
    if (!pairsWithFishOrDessert) return false;

    // Red or White wine
    // Varietals like Pinot Noir, Chardonnay, Pinot Gris, Riesling, etc.
    return true;
  });

  return {
    totalOregon: data.count,
    matchingCount: matches.length,
    matches: matches.map(m => ({
      title: m.title,
      price: m.price_excl_tax,
      expert_rating: m.expert_rating,
      expert_reviews: m.expert_reviews,
      food_pairings: m.food_pairings,
      varietal: m.main_varietal_text,
      wine_category: m.wine_category,
      url: m.url
    })).sort((a, b) => (b.expert_rating || 0) - (a.expert_rating || 0))
  };
});
