const tabId = 1962625075;
const fetchEndpoint = await browserjs(tabId, async () => {
  // Let's find scripts
  const scripts = Array.from(document.querySelectorAll('script[src*="_nuxt"]')).map(s => s.src);
  // Search for the productList fetch in scripts
  for (const src of scripts) {
    try {
      const res = await fetch(src);
      const text = await res.text();
      if (text.includes('productList-') || text.includes('/api/catalog/') || text.includes('/api/store/')) {
        const matches = text.match(/\/api\/[a-zA-Z0-9_\-\/]+/g) || [];
        return { src, matches: Array.from(new Set(matches)) };
      }
    } catch (e) {}
  }
  return 'Not found in searched scripts';
});
console.log(fetchEndpoint);

