const tabId = 1962625075;
const allWinesCheck = await browserjs(tabId, async () => {
  // Fetch all 212 wines across pages (page_size can be up to 100 or 250?)
  let page = 1;
  let allWines = [];
  while (true) {
    const res = await fetch(`/api/catalog/search/?page=${page}&page_size=100`);
    const data = await res.json();
    if (!data.results || data.results.length === 0) break;
    allWines.push(...data.results);
    if (allWines.length >= data.count) break;
    page++;
  }

  // Filter all wines from Oregon
  const oregonWines = allWines.filter(w => {
    const r = JSON.stringify(w.region || '').toLowerCase();
    const wr = (w.producing_winery_region || '').toLowerCase();
    const st = (w.available_states || []).map(s => s.toLowerCase());
    const title = (w.title || '').toLowerCase();
    const desc = (w.description || '').toLowerCase();
    const vc = (w.varietal_category || '').toLowerCase();
    return r.includes('oregon') || wr.includes('oregon') || vc.includes('willamette') || r.includes('willamette');
  });

  return {
    totalWines: allWines.length,
    totalOregon: oregonWines.length,
    oregonWines: oregonWines.map(w => ({
      id: w.id,
      title: w.title,
      name_text: w.name_text,
      price: w.price_excl_tax,
      retail_price: w.retail_price,
      expert_rating: w.expert_rating,
      expert_reviews: w.expert_reviews,
      food_pairings: w.food_pairings,
      wine_category: w.wine_category,
      varietal: w.main_varietal_text,
      url: w.url,
      region: w.region
    }))
  };
});
console.log(`Fetched ${allWinesCheck.totalWines} total wines. Found ${allWinesCheck.totalOregon} Oregon wines.`);
console.log(JSON.stringify(allWinesCheck.oregonWines, null, 2));

