  const wines = [
    { name: "Norris Riesling", url: "/catalog/2022-norris-estate-riesling-ribbon-ridge_93224a6c-18c4-4c0d-84f1-19ca6b7f55b3/" },
    { name: "Benmar Pinot Noir", url: "/catalog/2024-benmar-pinot-noir-above-the-clouds-willamette-valley_bdcf3165-e94a-41e5-b5b3-6d20528e6469/" },
    { name: "Silvan Ridge Pinot Noir", url: "/catalog/2022-silvan-ridge-winery-pinot-noir-willamette-valley_fc550264-6230-4877-9efe-10450a022502/" },
    { name: "Anderson Family Pinot Noir", url: "/catalog/2018-anderson-family-vineyard-pinot-noir-dundee-hills_966c4c34-ce82-4e90-98dd-500e7f38d826/" },
    { name: "Norris Pinot Noir", url: "/catalog/2023-norris-estate-pinot-noir-black-barn-norris-mckinley-vineyard-ribbon-ridge_c153806c-f882-4bca-bb05-bb034a04ac94/" }
  ];

  const results = [];
  for (const w of wines) {
    const res = await fetch(w.url);
    const html = await res.text();
    // Parse JSON from script tag or window.__NUXT__
    // Let's find product details inside html
    // Look for expert_reviews, expert_rating, food_pairings
    const expertReviewsMatch = html.match(/"expert_reviews":(\[[^\]]*\]|\{[^\}]*\})/);
    const expertRatingMatch = html.match(/"expert_rating":([0-9\.]+)/);
    const priceMatch = html.match(/"price_excl_tax":([0-9\.]+)/);
    const pairingsMatch = html.match(/"food_pairings":(\[[^\]]*\]|\{[^\}]*\})/);
    const wineCategoryMatch = html.match(/"wine_category":"([^"]*)"/);

    // Check if html mentions fish or dessert
    const mentionsFish = /fish/i.test(html);
    const mentionsDessert = /dessert/i.test(html);

    results.push({
      name: w.name,
      url: w.url,
      expert_rating: expertRatingMatch ? expertRatingMatch[1] : null,
      expert_reviews: expertReviewsMatch ? expertReviewsMatch[1].slice(0, 200) : null,
      price: priceMatch ? priceMatch[1] : null,
      food_pairings: pairingsMatch ? pairingsMatch[1] : null,
      wine_category: wineCategoryMatch ? wineCategoryMatch[1] : null,
      mentionsFish,
      mentionsDessert
    });
  }
  return results;
});
