const tabId = 1962625075;
const checkAllRegions = await browserjs(tabId, async () => {
  let page = 1;
  let allWines = [];
  while (true) {
    const res = await fetch(`/api/catalog/search/?page=${page}&page_size=100`);
    const data = await res.json();
    if (!data.results || data.results.length === 0) break;
    allWines.push(...data.results);
    if (allWines.length >= data.count) break;
    page++;
  }

  // Look for any US wines
  const usWines = allWines.filter(w => {
    const r = JSON.stringify(w.region || '').toLowerCase();
    const c = (w.country || '').toLowerCase();
    return c === 'united-states' || r.includes('united-states') || r.includes('america');
  });

  // Collect unique regions/appellations from US wines
  const usRegions = usWines.map(w => ({
    title: w.title,
    price: w.price_excl_tax,
    expert_rating: w.expert_rating,
    appellation: w.appellation,
    region: w.region,
    producing_winery_region: w.producing_winery_region,
    producing_winery: w.producing_winery,
    url: w.url
  }));

  return {
    totalWines: allWines.length,
    usWinesCount: usWines.length,
    usRegions
  };
});
console.log(`US Wines: ${checkAllRegions.usWinesCount}`);
// Print any US wines that are NOT in California or Washington
const nonCalWines = checkAllRegions.usRegions.filter(w => {
  const s = JSON.stringify(w).toLowerCase();
  return !s.includes('california') && !s.includes('napa') && !s.includes('sonoma') && !s.includes('paso');
});
console.log(`Non-California US wines: ${nonCalWines.length}`);
console.log(JSON.stringify(nonCalWines, null, 2));

