const pdpInspect = await browserjs(tabId, async () => {
  // Let's inspect the page content of Benmar Pinot Noir and Norris Riesling
  async function getWineDetails(url) {
    const res = await fetch(url);
    const html = await res.text();
    // find __NUXT_DATA__ or __NUXT__
    const nuxtDataMatch = html.match(/<script type="application\/json" id="__NUXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
    let nuxtData = null;
    if (nuxtDataMatch) {
      try {
        nuxtData = JSON.parse(nuxtDataMatch[1]);
      } catch (e) {}
    }
    return {
      url,
      nuxtDataLength: nuxtData ? nuxtData.length : 0,
      nuxtData: nuxtData ? nuxtData.filter(x => typeof x === 'string' && (x.includes('Point') || x.includes('fish') || x.includes('dessert') || x.includes('score') || x.includes('Decanter') || x.includes('Suckling') || x.includes('Advocate') || x.includes('Spectator') || x.includes('Vinous'))) : null,
      title: html.match(/<title>([^<]*)<\/title>/)?.[1]
    };
  }

  return {
    norris: await getWineDetails("/catalog/2022-norris-estate-riesling-ribbon-ridge_93224a6c-18c4-4c0d-84f1-19ca6b7f55b3/"),
    benmar: await getWineDetails("/catalog/2024-benmar-pinot-noir-above-the-clouds-willamette-valley_bdcf3165-e94a-41e5-b5b3-6d20528e6469/"),
    silvan: await getWineDetails("/catalog/2022-silvan-ridge-winery-pinot-noir-willamette-valley_fc550264-6230-4877-9efe-10450a022502/")
  };
});
