    const main = doc.querySelector('main') || doc.body;
    return {
      url,
      h1: doc.querySelector('h1')?.textContent.trim(),
      h2: Array.from(doc.querySelectorAll('h2')).map(h => h.textContent.trim()),
      pointsBadge: Array.from(doc.querySelectorAll('[class*="point"], [class*="badge"], [class*="score"], [class*="rating"]')).map(el => el.textContent.trim().replace(/\s+/g, ' ')),
      pairings: Array.from(doc.querySelectorAll('[class*="pairing"], [class*="food"]')).map(el => el.textContent.trim().replace(/\s+/g, ' ')),
      story: doc.querySelector('.story, .description, [class*="story"], [class*="desc"]')?.textContent.trim().replace(/\s+/g, ' ').slice(0, 300)
    };
  }

  return {
    norris: await parsePage("/catalog/2022-norris-estate-riesling-ribbon-ridge_93224a6c-18c4-4c0d-84f1-19ca6b7f55b3/"),
    benmar: await parsePage("/catalog/2024-benmar-pinot-noir-above-the-clouds-willamette-valley_bdcf3165-e94a-41e5-b5b3-6d20528e6469/")
