    "/catalog/2022-norris-estate-riesling-ribbon-ridge_93224a6c-18c4-4c0d-84f1-19ca6b7f55b3/",
    "/catalog/2024-benmar-pinot-noir-above-the-clouds-willamette-valley_bdcf3165-e94a-41e5-b5b3-6d20528e6469/",
